import{_ as a,o as e,c as t,a0 as i}from"./chunks/framework.DQOulFGV.js";const k=JSON.parse('{"title":"第5章 Netty：Java 高性能网络框架","description":"","frontmatter":{},"headers":[],"relativePath":"java/04-network/chapter-05-netty.md","filePath":"java/04-network/chapter-05-netty.md"}'),n={name:"java/04-network/chapter-05-netty.md"};function p(o,s,l,d,r,h){return e(),t("div",null,[...s[0]||(s[0]=[i(`<h1 id="第5章-netty-java-高性能网络框架" tabindex="-1">第5章 Netty：Java 高性能网络框架 <a class="header-anchor" href="#第5章-netty-java-高性能网络框架" aria-label="Permalink to &quot;第5章 Netty：Java 高性能网络框架&quot;">​</a></h1><blockquote><p>面试官问 Netty 的线程模型——你说得出 Boss/Worker，但说不清为什么一个 EventLoop 绑一个 Channel 就不用加锁、dispatcher 决定「在哪跑」和 threadpool 决定「用多大池子接」之间的区别、以及 <code>§5.3</code> 那个 <code>Direct buffer memory</code> OOM 为什么堆还有空间照样炸。本章拆穿&quot;Netty 就是 NIO 封装&quot;这种半对半错的理解——EventLoop 不是线程池、ByteBuf 不是 Buffer、Pipeline 不是责任链那么简单。</p></blockquote><blockquote><p><strong>📖 阅读建议</strong>：§5.1 是为什么要有 Netty（对比第4章 NIO），§5.2 是核心线程模型（你线上排障最需要的部分），§5.3 ByteBuf（<code>Direct buffer memory</code> OOM 根因），§5.4 编解码（粘包/拆包解决方案），§5.5 Reactor 模式全景。删除API罗列式讲解，保留原理和排查路径。</p></blockquote><hr><h2 id="_5-1-从-nio-到-netty-为什么原生-nio-没人直接用了" tabindex="-1">5.1 从 NIO 到 Netty：为什么原生 NIO 没人直接用了 <a class="header-anchor" href="#_5-1-从-nio-到-netty-为什么原生-nio-没人直接用了" aria-label="Permalink to &quot;5.1 从 NIO 到 Netty：为什么原生 NIO 没人直接用了&quot;">​</a></h2><p>第4章讲了 NIO 的 Channel、Buffer、Selector。你能用 500 行写一个 NIO Echo Server，但第4章也在末尾告诉你：生产代码没人这么写。具体原因一个一个看。</p><h3 id="_5-1-1-nio-的三个致命缺陷" tabindex="-1">5.1.1 NIO 的三个致命缺陷 <a class="header-anchor" href="#_5-1-1-nio-的三个致命缺陷" aria-label="Permalink to &quot;5.1.1 NIO 的三个致命缺陷&quot;">​</a></h3><table tabindex="0"><thead><tr><th>缺陷</th><th>后果</th></tr></thead><tbody><tr><td><strong>Buffer 的 flip/clear/compact</strong></td><td>读写模式手动切，忘记一次 flip → 读到错误数据，且不报错</td></tr><tr><td><strong>epoll 空轮询 Bug（JDK-6670302）</strong></td><td><code>selector.select()</code> 偶发立即返回 0 → CPU 空转 100%</td></tr><tr><td><strong>缺少编解码、线程模型、连接管理</strong></td><td>粘包要自己写、半包要自己攒、线程调度要自己管</td></tr></tbody></table><p>Netty 把这三个坑全部填平了。</p><h3 id="_5-1-2-netty-填了什么" tabindex="-1">5.1.2 Netty 填了什么 <a class="header-anchor" href="#_5-1-2-netty-填了什么" aria-label="Permalink to &quot;5.1.2 Netty 填了什么&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────┐</span></span>
<span class="line"><span>│         业务代码 (你的 Dubbo Consumer)│</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│         Netty 框架层                 │</span></span>
<span class="line"><span>│  ┌──────────┬──────────┬─────────┐  │</span></span>
<span class="line"><span>│  │ Pipeline │ ByteBuf  │ Codec   │  │</span></span>
<span class="line"><span>│  │ EventLoop│ Bootstrap│ Future  │  │</span></span>
<span class="line"><span>│  └──────────┴──────────┴─────────┘  │</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│         Java NIO (Channel/Selector) │</span></span>
<span class="line"><span>├─────────────────────────────────────┤</span></span>
<span class="line"><span>│         操作系统 (epoll/kqueue)      │</span></span>
<span class="line"><span>└─────────────────────────────────────┘</span></span></code></pre></div><table tabindex="0"><thead><tr><th>NIO 坑</th><th>Netty 对策</th></tr></thead><tbody><tr><td>Buffer flip 繁琐</td><td>ByteBuf 读写指针分离，自动扩容，不需要 flip</td></tr><tr><td>epoll 空轮询 Bug</td><td>连续 512 次空返回 → 重建 Selector</td></tr><tr><td>缺少协议支持</td><td>内置 HTTP/WebSocket/SSL 编解码器</td></tr><tr><td>粘包/拆包</td><td>内置 LengthField / Delimiter / FixedLength 帧解码器</td></tr><tr><td>线程模型缺失</td><td>EventLoopGroup + Pipeline，一行代码绑到线程池</td></tr></tbody></table><p>Netty 在 Java 生态中是事实标准：Dubbo 的传输层、gRPC 的 Netty Transport、Elasticsearch 节点间通信、RocketMQ 的网络层，全都跑在 Netty 上。</p><hr><h2 id="_5-2-eventloop-线程模型-dubbo「线程池打满」的根" tabindex="-1">5.2 EventLoop 线程模型：Dubbo「线程池打满」的根 <a class="header-anchor" href="#_5-2-eventloop-线程模型-dubbo「线程池打满」的根" aria-label="Permalink to &quot;5.2 EventLoop 线程模型：Dubbo「线程池打满」的根&quot;">​</a></h2><p>回到开头那个故障。Dubbo Provider 200 个线程全部耗尽，但你的服务一共才 4 个 CPU 核。为什么会有 200 个线程同时在跑？因为 Dubbo 默认用 Netty 的 <strong>EventLoop + 业务线程池</strong> 两层模型——失败不在 Netty 的 IO 层，而在业务线程池层。</p><h3 id="_5-2-1-boss-和-worker-连接和数据分开管" tabindex="-1">5.2.1 Boss 和 Worker：连接和数据分开管 <a class="header-anchor" href="#_5-2-1-boss-和-worker-连接和数据分开管" aria-label="Permalink to &quot;5.2.1 Boss 和 Worker：连接和数据分开管&quot;">​</a></h3><p>Netty 服务端有两个线程组：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bossGroup (1 个线程)                workerGroup (CPU×2 个线程)</span></span>
<span class="line"><span>┌────────────────┐                 ┌────────────────────┐</span></span>
<span class="line"><span>│  NioEventLoop   │                 │  NioEventLoop-1    │</span></span>
<span class="line"><span>│  Selector       │  ── accept ──→  │  Channel A, B, C   │</span></span>
<span class="line"><span>│  只做 accept()  │  分配 Channel   │  read/write/decode │</span></span>
<span class="line"><span>└────────────────┘                 ├────────────────────┤</span></span>
<span class="line"><span>                                   │  NioEventLoop-2    │</span></span>
<span class="line"><span>                                   │  Channel D, E      │</span></span>
<span class="line"><span>                                   │  read/write/decode │</span></span>
<span class="line"><span>                                   └────────────────────┘</span></span></code></pre></div><p><strong>bossGroup 只管 accept</strong>：一条线程收到新连接后，按 Round-Robin 分给 workerGroup 的某个 EventLoop。<strong>workerGroup 负责读数据</strong>：从 Channel 读字节 → 解码 → 触发 Handler。</p><p><strong>关键规则</strong>：一个 Channel 的所有 I/O 事件永远由同一个 EventLoop 线程处理。这意味着你在 I/O Handler 里不需要加锁——天然的线程安全。但也意味着你不能阻塞 EventLoop 线程——一个 Handler 里加了 <code>sleep</code>，这个 EventLoop 上所有 Channel 全部罢工。</p><h3 id="_5-2-2-dubbo-的-dispatcher-和-threadpool-io-线程和业务线程的分工" tabindex="-1">5.2.2 Dubbo 的 dispatcher 和 threadpool：IO 线程和业务线程的分工 <a class="header-anchor" href="#_5-2-2-dubbo-的-dispatcher-和-threadpool-io-线程和业务线程的分工" aria-label="Permalink to &quot;5.2.2 Dubbo 的 dispatcher 和 threadpool：IO 线程和业务线程的分工&quot;">​</a></h3><p>Dubbo 在 Netty workerGroup 之上又加了一层业务线程池。控制「谁出谁进」的是 <code>dispatcher</code>：</p><table tabindex="0"><thead><tr><th>dispatcher</th><th>行为</th><th>代价</th></tr></thead><tbody><tr><td><code>all</code>（默认）</td><td>所有消息都丢给业务线程池</td><td>多一次线程切换</td></tr><tr><td><code>direct</code></td><td>所有消息都留在 I/O 线程上处理</td><td>Handler 里不能有任何阻塞</td></tr><tr><td><code>message</code></td><td>只有请求进业务线程池，响应留在 I/O 线程</td><td>折中</td></tr><tr><td><code>execution</code></td><td>只有请求进业务线程池，响应也留在 I/O 线程</td><td>和 message 类似</td></tr></tbody></table><p><strong>dispatcher 和 threadpool 解决的不是一个问题</strong>：</p><ul><li><strong>dispatcher</strong> 决定「这个 Handler 在哪个线程上跑」——I/O 线程还是业务线程。</li><li><strong>threadpool</strong> 决定「进了业务线程池后，用多大的池子来接」。</li></ul><p>很多线上调参无效就是因为搞混了这两层。你调大 <code>threads=500</code>，但如果 dispatcher 选的 <code>direct</code>，消息根本没进业务线程池——加再多 threads 也没用。</p><p>回到开头那个故障：dispatcher 用的是 <code>all</code>，threadpool 用的是 <code>fixed:200</code>。一个测试残留的 <code>sleep(6000)</code> 把 200 个业务线程全部占满。后续新请求进入业务线程池时被 <code>AbortPolicyWithReport</code> 拒绝，Dubbo 会返回 <code>SERVER_THREADPOOL_EXHAUSTED_ERROR</code> 给 Consumer。Consumer 如果设了 <code>retries&gt;0</code>，重试又会涌进来更多请求→雪崩。</p><h3 id="_5-2-3-eventloop-任务队列-别阻塞-i-o-线程" tabindex="-1">5.2.3 EventLoop 任务队列：别阻塞 I/O 线程 <a class="header-anchor" href="#_5-2-3-eventloop-任务队列-别阻塞-i-o-线程" aria-label="Permalink to &quot;5.2.3 EventLoop 任务队列：别阻塞 I/O 线程&quot;">​</a></h3><p>Netty 的 EventLoop 不仅处理 I/O 事件，还执行用户提交的任务：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ✅ 耗时操作交给独立业务线程池</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">EventLoopGroup businessGroup </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> DefaultEventLoopGroup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ch.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pipeline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addLast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(workerGroup, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;codec&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> HttpCodecHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">())   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// I/O 线程</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addLast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(businessGroup, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;biz&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BusinessHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 业务线程池</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ❌ 耗时操作直接霸占 I/O 线程</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ch.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pipeline</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addLast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> BusinessHandler</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 跑在 workerGroup 上</span></span></code></pre></div><hr><h2 id="_5-3-bytebuf-你线上见过但没看懂的-direct-buffer-memory-oom" tabindex="-1">5.3 ByteBuf：你线上见过但没看懂的 <code>Direct buffer memory</code> OOM <a class="header-anchor" href="#_5-3-bytebuf-你线上见过但没看懂的-direct-buffer-memory-oom" aria-label="Permalink to &quot;5.3 ByteBuf：你线上见过但没看懂的 \`Direct buffer memory\` OOM&quot;">​</a></h2><p>Netty 的 ByteBuf 用一个独立指针 <code>readerIndex</code> 和一个独立指针 <code>writerIndex</code> 替代了 NIO Buffer 的单一 position。不需要 flip，不需要 compact——读就自动移动 <code>readerIndex</code>，写就自动移动 <code>writerIndex</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>+-------------------+------------------+------------------+</span></span>
<span class="line"><span>| 已读/可丢弃       |  可读数据         |  可写空间         |</span></span>
<span class="line"><span>+-------------------+------------------+------------------+</span></span>
<span class="line"><span>0              readerIndex        writerIndex        capacity</span></span></code></pre></div><p>ByteBuf 默认使用池化的堆外内存（PooledDirectByteBuf）。堆外内存不受 JVM GC 管理，这意味着：你线上堆还有 2GB 空闲，但 Netty 的 PooledDirectByteBuf 已经把堆外内存吃了几百 MB，JVM 发现不了。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>java.lang.OutOfMemoryError: Direct buffer memory</span></span></code></pre></div><p>这就是那道令无数开发者困惑的 OOM。堆里明明闲着，为什么会 OOM？因为 <code>-XX:MaxDirectMemorySize</code> 默认等于 <code>-Xmx</code>，而 Netty 的 ByteBuf 全部走堆外。</p><p>排查命令：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 看堆外内存使用（需要 JDK 9+）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">jcmd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">pi</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> VM.native_memory</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> summary</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Direct&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 开 Netty 内存泄漏检测</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">-Dio.netty.leakDetection.level</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">=PARANOID</span></span></code></pre></div><p>引用计数是 ByteBuf 的另一道防线。每个 ByteBuf 创建后 <code>refCnt=1</code>，每 <code>retain()</code> 一次 +1，每 <code>release()</code> 一次 -1，归零后释放内存。Netty 的 <code>SimpleChannelInboundHandler</code> 会自动 <code>release()</code>，但自定义 Handler 里如果手动 <code>retain()</code> 了却忘记 <code>release()</code> → 永久泄漏。</p><hr><h2 id="_5-4-编解码-tcp-粘包-拆包的工业化解决方案" tabindex="-1">5.4 编解码：TCP 粘包/拆包的工业化解决方案 <a class="header-anchor" href="#_5-4-编解码-tcp-粘包-拆包的工业化解决方案" aria-label="Permalink to &quot;5.4 编解码：TCP 粘包/拆包的工业化解决方案&quot;">​</a></h2><p>TCP 没有消息边界。你发了两条消息，对方可能收到一条「粘在一起」的数据。Netty 内置了三种帧解码器：</p><table tabindex="0"><thead><tr><th>解码器</th><th>原理</th><th>适用协议</th></tr></thead><tbody><tr><td><code>FixedLengthFrameDecoder</code></td><td>每条消息固定 N 字节</td><td>简单私有协议</td></tr><tr><td><code>DelimiterBasedFrameDecoder</code></td><td>用特殊字符分隔（如 <code>\\r\\n</code>）</td><td>文本协议（Redis）</td></tr><tr><td><code>LengthFieldBasedFrameDecoder</code></td><td>消息头 N 字节 = 消息体长度</td><td>大多数二进制协议（Dubbo）</td></tr></tbody></table><p><code>LengthFieldBasedFrameDecoder</code> 是最常用的，Dubbo 协议帧本身就是这个模式：</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// maxFrameLength=65535, offset=0, length=4B, strip=4B</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pipeline.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addLast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LengthFieldBasedFrameDecoder</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">65535</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span></code></pre></div><p>帧解码之后的数据才能交给业务 Handler。如果在帧解码之前解码了 —— 你拿到了半条消息或者两条消息粘在一起的数据，然后你的业务代码按「完整消息」来解析，不是报错就是静默丢数据。</p><hr><h2 id="_5-5-reactor-模式全景-从单线程到主从" tabindex="-1">5.5 Reactor 模式全景：从单线程到主从 <a class="header-anchor" href="#_5-5-reactor-模式全景-从单线程到主从" aria-label="Permalink to &quot;5.5 Reactor 模式全景：从单线程到主从&quot;">​</a></h2><p>把 EventLoop、Pipeline、编解码器串起来，一次请求的完整旅程：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bossGroup (accept) → workerGroup (read/decode) → [可选: businessGroup (业务)]</span></span>
<span class="line"><span>                                                       ↓</span></span>
<span class="line"><span>                                                    Pipeline:</span></span>
<span class="line"><span>                                          Head → FrameDecoder → Codec → BizHandler → Tail</span></span></code></pre></div><p>Netty 的主从 Reactor 模型和 Tomcat 的 Acceptor/Poller/Worker 三线程模型是同一种思想的不同实现。区别在于 Tomcat 是为 HTTP 优化的 Servlet 容器，Netty 是通用网络框架——你可以用它写 HTTP 服务器，也可以写 RPC 框架、消息队列、IM 服务。</p><hr><blockquote><p><strong>纵横联系</strong></p><ul><li><strong>第4章 NIO</strong> 的 Selector + Channel + Buffer 是 Netty 的地基。你在 Netty 里看到的 <code>NioEventLoop</code>、<code>NioSocketChannel</code>、<code>ByteBuf</code> 都是对 NIO 的装箱。</li><li><strong>第7章 Servlet</strong> 的 Tomcat NioEndpoint 和本章 Netty 的主从 Reactor 是同一种模式——Tomcat 用 Java NIO 自建，Netty 做了更通用的封装。</li><li><strong>第8章 RPC</strong> 的 Dubbo 传输层基于 Netty。Dubbo 的 dispatcher/threadpool 配置直接影响 Netty EventLoop 的业务线程分配策略。</li></ul></blockquote>`,55)])])}const y=a(n,[["render",p]]);export{k as __pageData,y as default};
